export function reconcileEvents(current, incoming) {
  const map = new Map();

  // Traverse current events in order, storing the first occurrence of each id
  for (const ev of current) {
    if (!map.has(ev.id)) {
      map.set(ev.id, ev);
    }
  }

  // Build a new array maintaining current's order
  const result = [];
  for (const ev of current) {
    result.push(map.get(ev.id));
  }

  // Process incoming events
  for (const ev of incoming) {
    map.set(ev.id, ev); // latest wins
    // If this id already appears earlier in result, update it in place
    const idx = result.findIndex(e => e.id === ev.id);
    if (idx !== -1) {
      result[idx] = ev;
    } else {
      // New id: append while preserving existing order
      result.push(ev);
    }
  }

  return result;
}
